(()=>{const b=window.DriveQuizBank;if(!b)throw Error("Missing DriveQuizBank");b.questions.push(...[{"id":"rodrive-b-0751","batch":"16","category":"Categoria B","question":"În această situație, cui trebuie să acordați prioritate?","answers":["Vehiculelor care circulă pe drumul transversal","Vehiculelor care circulă din partea stângă","Niciunui vehicul"],"correctIndices":[0],"correct":0,"explanation":"În situația dată, întâlniți indicatorul “Cedează trecerea”, indicator care vă obligă la reducerea vitezei de deplasare și la acordarea de prioritate. Presupunând că veți circula pe direcția înainte, veți acorda prioritate de trecere tuturor vehiculelor care au acest drept, în acest caz, tuturor vehiculelor care circulă pe drumul transversal. În cazul în care vreți să executați virajul la stânga, pe lângă prioritatea acordată celor de pe drumul transversal, trebuie să acordați prioritate și vehiculelor care vin din sens opus.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0751.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0751.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 751; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Indicatorul triunghiular cu margini roșii, 'Cedează trecerea', este plasat în dreptul șoferului. Șoferul intenționează să meargă înainte.","needsImageReview":true,"source":"RoDrive · ID 750 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-aceasta-situatie-cui-trebuie-sa-acordati-prioritate","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"750","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_775.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0752","batch":"16","category":"Categoria B","question":"Indicatorul semnifică o viteză:","answers":["Maximă","Informativă","Minimă obligatorie"],"correctIndices":[2],"correct":2,"explanation":"Indicatorul pe care l-ați întâlnit se numește “Viteza minimă obligatorie” acesta impune o viteză minimă obligatorie de 30 de km/h. În situația dată trebuie să circulați cu o viteză mai mare decât cea înscrisă pe indicator. De exemplu, dacă vă deplasați cu o viteza de 26 de km/h, înseamnă că nu respectați semnificația indicatorului și circulați neregulamentar. Trebuie să țineți cont că nu trebuie să depășiți nici viteza maximă admisă pe sectorul de drum respectiv, pentru categoria de vehicul pe care o conduceți. În cazul în care sunteți depistat că vă deplasați în mod nejustificat cu o vitezăcu cel puţin 10 km/h sub limita minimă, veți fi sancționat cu amenda prevăzută în clasa I de sancțiuni.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0752.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0752.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 752; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un drum cu un indicator circular albastru, pe care scrie 30, ce reprezintă viteza minimă impusă de 30 km/h.","needsImageReview":true,"source":"RoDrive · ID 751 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/indicatorul-semnifica-o-viteza","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"751","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_776.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0753","batch":"16","category":"Categoria B","question":"Care dintre autoturismele din imagine circulă corect în intersecție?","answers":["Autoturismul mov și cel roșu","Autoturismul albastru și cel roșu","Toate cele patru autoturisme"],"correctIndices":[2],"correct":2,"explanation":"În această intersecție cu circulație în sens giratoriu: Prin urmare, toate autoturismele circulă corect în această intersecție cu sens giratoriu. Dar acestea trebuie să respecte regulile cu privire la semnalizarea schimbării direcției de mers, acordarea priorității la schimbarea benzii de circulație și acordarea priorității la intrarea în sensul giratoriu.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0753.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0753.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 753; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție giratorie, unde fiecare vehicul este încadrat pe banda corespunzătoare direcției dorite și se află în sensul giratoriu. Vehiculele galben și albastru urmează direcții diferite, iar vehiculele roșu și violet se deplasează pe banda exterioară. Fiecare vehicul merge în sensul corespunzător și pe banda corespunzătoare direcției de mers.","needsImageReview":true,"source":"RoDrive · ID 752 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-dintre-autoturismele-din-imagine-circula-corect-in-intersectie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"752","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_777.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0754","batch":"16","category":"Categoria B","question":"Precizați care vehicule sunt exceptate de la obligația acordării priorității de trecere:","answers":["Cele care se pun în mișcare de pe loc față de cele care circulă","Autovehiculele din serviciile regulate de transport public, care se pun în mișcare din stația prevăzută cu alveolă","Cele care ies din curți, ganguri sau garaje"],"correctIndices":[1],"correct":1,"explanation":"Vehiculele care se pun în mișcare de pe loc trebuie să acorde prioritate de trecere vehiculelor care circulă pe drumul public, indiferent de sensul acestora de deplasare. Atunci când vă apropiați de o stație pentru mijloace de transport public de persoaneprevăzută cu alveolă, circulând pe banda de lângă acostament sau bordură, iar autobuzul aflat oprit în stație semnalizează intenția de a ieși, aveți obligația de a reduce viteza și la nevoie să opriți pentru a-i permite acestuia să reintre în trafic. Trebuie să reținem că autobuzul al cărui conducător semnalizează intenția de a reintra în trafic din stația prevăzută cu alveolă are prioritateDOAR față de vehiculele care circulă din spatele acestuia, iar dacă drumul are mai multe benzi pe sens acesta are prioritateDOAR față de vehiculele care circulă din spatele acestuiape prima bandă. Vehiculele care pătrund pe un drum public, venind de pe proprietăți alăturate drumului public, trebuie să acorde prioritate de trecere vehiculelor care circulă pe drumul public, indiferent de sensul acestora de deplasare.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0754.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0754.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 754; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 753 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/precizati-care-vehicule-sunt-exceptate-de-la-obligatia-acordarii-prioritatii-de-trecere","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"753","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0755","batch":"16","category":"Categoria B","question":"Care dintre indicatoare conferă prioritatea de trecere?","answers":["Indicatorul 1","Indicatorul 2","Indicatorul 3"],"correctIndices":[0],"correct":0,"explanation":"La întâlnirea indicatorului „Prioritatefațăde circulația din sens invers” conducătorul de vehicul are prioritate față de toate vehiculele care circulă din sens opus. Acest indicator rutier se întâlnește pe sectoarele de drum îngustat, unde nu au loc să circule două vehicule, unul pe lângă celălalt. Indicatorul „Circulație în ambele sensuri” se întâlnește la ieșire de pe un drum cu sens unic și are rolul de a atenționa conducătorul de autovehicul că pe sectorul de drum următor se va circula în ambele sensuri. La întâlnirea indicatorului „Prioritatepentrucirculația din sens invers”, conducătorul de vehicul pierde prioritatea față de toate vehiculele care circulă din sens opus. Acest indicator rutier se întâlnește pe sectoarele de drum îngustat, unde nu au loc să circule două vehicule, unul pe lângă celălalt. Prin urmare, veți avea prioritate de trecere la întâlnirea indicatorului 1 „Prioritatefațăde circulația din sens invers”.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0755.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0755.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 755; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă trei indicatoare rutiere care reglementează prioritatea în cazul circulației pe drumuri îngustate: 1) Indicatorul albastru cu săgeata albă din dreapta orientată în sus și săgeata roșie din stânga orientată în jos semnifică 'Prioritate față de circulația din sens invers'; 2) Indicatorul triunghiular cu margine roșie și două săgeți negre, cea din dreapta în sus și cea din stânga în jos avertizează șoferul că urmează un sector de drum îngustat cu circulație pe ambele sensuri; 3) Indicatorul circular cu chenar roșu și săgeata roșie în dreapta orientată în sus și săgeată neagră în stânga, orientată în jos, semnifică 'Prioritate pentru circulația din sens invers'.","needsImageReview":true,"source":"RoDrive · ID 754 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-dintre-indicatoare-confera-prioritatea-de-trecere","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"754","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_779.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0756","batch":"16","category":"Categoria B","question":"Ce obligații revin conducătorilor de vehicule la trecerea autovehiculelor cu regim de circulație prioritară, care au în funcțiune mijloacele speciale de avertizare luminoasă de culoare roșie și pe cele de avertizare sonoră:","answers":["Să oprească imediat pe acostament sau, în lipsa acestuia, cât mai aproape de marginea drumului sau de bordura trotuarului, în sensul de deplasare","Să reducă viteza și să circule cât mai aproape de marginea drumului în sensul de deplasare","Să scoată vehiculul în afara drumului, indiferent prin ce mijloace"],"correctIndices":[0],"correct":0,"explanation":"Atunci când întâlniți autovehicule cu regim de circulație prioritară care au în funcțiune mijloacele speciale de avertizare luminoasă de culoare roșie și pe cele sonore, aveți obligația să opriți imediat autovehiculul pe acostament sau în lipsa acestuia, cât mai aproape de marginea drumului sau bordura trotuarului, în sensul de deplasare. După trecerea acestora vă puteți continua deplasarea. Trebuie să știm că acestora le este permis să folosească semnalele luminoase fără a fi însoţite de cele sonore, în funcţie de natura misiunii ori de condiţiile de trafic, situaţie în care autovehiculul respectiv nu are regim de circulaţie prioritară. Dar situația inversă, să folosească doar semnalele sonore, fără a fi însoţite de cele luminoase, le este interzisă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0756.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0756.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 756; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 755 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-revin-conducatorilor-de-vehicule-la-trecerea-autovehiculelor-cu-regim-de-circulatie-prioritara-care-au-in-functiune-mijloacele-","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"755","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0757","batch":"16","category":"Categoria B","question":"Conducătorilor de vehicule le este interzis:","answers":["Să profereze injurii","Să săvârșească acte sau gesturi obscene","Să adreseze celorlalți participanți la trafic expresii jignitoare sau vulgare"],"correctIndices":[0,1,2],"correct":0,"explanation":"Este interzis conducătorilor de autovehicule să profereze injurii, să săvârșească acte sau gesturi obscene sau să adreseze celorlalți participanți la trafic expresii jignitoare sau vulgare.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0757.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0757.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 757; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 756 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/conducatorilor-de-vehicule-le-este-interzis","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"756","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0758","batch":"16","category":"Categoria B","question":"Semaforul de avertizare constituit dintr-un corp de iluminat de culoare galbenă intermitentă vă obligă:","answers":["Să acordați prioritate de trecere","Să circulați cu viteză redusă","Să opriți în orice situație"],"correctIndices":[1],"correct":1,"explanation":"Semaforul de avertizare constituit dintr-un corp de iluminat cu lumină galbenă intermitentă obligă la reducerea vitezei și sporirea atenției, deoarece urmează un loc periculos, ca de exemplu o trecere pentru pietoni. Acest semafor de avertizare se instalează, de regulă, la ieșirea din intersecție și poate avea în câmpul sau imaginea unui pieton în mișcare, de culoare galbenă pe fond negru.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0758.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0758.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 758; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 757 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/semaforul-de-avertizare-constituit-dintr-un-corp-de-iluminat-de-culoare-galbena-intermitenta-va-obliga","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"757","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0759","batch":"16","category":"Categoria B","question":"Ce rând trebuie să ocupați și de la ce distanță, pentru a putea executa virajul la stânga într-o intersecție nedirijată?","answers":["Rândul de lângă axa drumului, de la o distanță de cel puțin 50 m","Rândul din mijloc, de la o distanță de cel puțin 100 m","Rândul de lângă bordură, de la o distanță de cel puțin 50 m"],"correctIndices":[0],"correct":0,"explanation":"Atunci când doriți să virați către stânga într-o intersecțiefără marcaje de delimitare a benzilor, mai exactcând drumul are o singură bandă pe sensul de mers, indiferent dacă circulația în aceasta este dirijată sau nedirijată, trebuie să ocupați în mers,cu cel puțin 50 de metri înainte de intersecțierândul de lânga axa drumului sau de lânga marcajul de separare a sensurilor. Atunci când circulați pe un drum cu sens unic, trebuie să ocupați rândul de lânga bordură sau acostament din partea stânga.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0759.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0759.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 759; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 758 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-rand-trebuie-sa-ocupati-si-de-la-ce-distanta-pentru-a-putea-executa-virajul-la-stanga-intr-o-intersectie-nedirijata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"758","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0760","batch":"16","category":"Categoria B","question":"În ce situații nu vă este permisă depășirea?","answers":["Când un autobuz se află oprit în stație","Pe un drum în rampă, când vizibilitatea este peste 50 m","Într-o intersecție nedirijată"],"correctIndices":[2],"correct":2,"explanation":"Atunci când întâlniți un autobuz oprit în stație puteți efectua manevra de depășire a acestuia, dar trebuie să circulați cu atenție sporită. Pe drumurile în rampă, unde vizibilitatea estePESTE50 de metri este permisă depășirea, fiind interzisă pe drumurile în rampă, unde vizibilitatea esteSUB50 de metri. Această diferență „peste/sub 50 metri” face ca varianta B să nu fie corectă. Depășirea vehiculelor nu vă este permisă în intersecțiile cu circulație nedirijată.Atenție!În aceste situații se interzice depășirea tuturor vehiculelor, chiar și depășirea bicicletelor.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0760.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0760.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 760; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 759 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-ce-situatii-nu-va-este-permisa-depasirea","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"759","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0761","batch":"16","category":"Categoria B","question":"Viteza maximă cu care pot să conducă un autoturism, pe autostradă, persoanele care au mai puțin de un an de practică de conducere, este de:","answers":["130 km/h","100 km/h","110 km/h"],"correctIndices":[2],"correct":2,"explanation":"Viteza maximă în afara localităților pentru conducătorii autovehiculelor din categoria B, care au mai puțin de 1 an practică de conducere, este cu20 km/h mai micădecât viteza maximă admisă pentru categoria din care face parte autovehiculul condus. Având în vedere că viteza maximă, pe autostrăzi, pentru autovehiculele din categoria B este de 130 de km/h, cei care au mai puțin de 1 an practică de conducere vor circula pe autostrăzicu o viteză maximă de 110 km/h.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0761.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0761.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 761; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 760 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/viteza-maxima-cu-care-pot-sa-conduca-un-autoturism-pe-autostrada-persoanele-care-au-mai-putin-de-un-an-de-practica-de-conducere-este-de","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"760","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0762","batch":"16","category":"Categoria B","question":"Ce obligații aveți la trecerea pentru pietoni, pe sensul dvs. de mers?","answers":["Să acordați prioritate de trecere și pietonilor care circulă pe celălalt sens de mers","Să reduceți viteza și să vă strecurați printre pietoni","Să acordați prioritate de trecere pietonilor aflați în traversare"],"correctIndices":[2],"correct":2,"explanation":"Obligația de a acorda prioritate vă revine doar în cazul pietonilor care se află în traversare pe sensul dvs. de mers, nu și în cazul pietonilor care circulă pe celălalt sens de mers. Având în vedere ca aveți obligația de a le acorda prioritate acestora, vă este strict interzis să vă strecurați printre aceștia, ar fi caz de neacordare de prioritate. Aveți obligația de a acorda prioritate de trecere pietonului care traversează drumul public, prin loc special amenajat, marcat și semnalizat corespunzător ori la culoarea verde a semaforului destinat lui, atunci când acesta se afla pe sensul dumneavoastră de mers.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0762.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0762.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 762; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 761 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-aveti-la-trecerea-pentru-pietoni-pe-sensul-dvs-de-mers","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"761","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0763","batch":"16","category":"Categoria B","question":"În care dintre următoarele situații nu este permisă depășirea?","answers":["Când autobuzul se află oprit în stație","În apropierea vârfurilor de rampă, când vizibilitatea este sub 50 m","Într-o intersecție nedirijată"],"correctIndices":[1,2],"correct":1,"explanation":"Atunci când întâlniți un autobuz oprit în stație, puteți efectua manevra de depășire a acestuia, dar trebuie să circulați cu atenție sporită. Depășirea vehiculelor nu vă este permisă pe drumurile în rampă unde vizibilitatea este redusă sub 50 de metri. Depășirea vehiculelor nu vă este permisă în intersecțiile cu circulație nedirijată.Atenție!, în aceste situații se interzice depășirea tuturor vehiculelor, chiar și depășirea bicicletelor sau trotinetelor electrice.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0763.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0763.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 763; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 762 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-care-dintre-urmatoarele-situatii-nu-este-permisa-depasirea","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"762","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0764","batch":"16","category":"Categoria B","question":"În ce situație se poate încălca marcajul longitudinal continuu al axului drumului?","answers":["Atunci când este format dintr-o singură linie","Atunci când linia continuă este însoțită de una discontinuă, dispusă către partea conducătorului","Atunci când drumul este în aliniament, iar vizibilitatea în față este asigurată"],"correctIndices":[1],"correct":1,"explanation":"Indiferent dacă marcajul longitudinal continuu al axului drumului este format dintr-o singură linie continuă sau din două linii continue, legislația rutieră interzice încălcarea acestuia. Marcajul longitudinal format dintr-o linie discontinuă simplă sau dublă, permite trecerea peste acesta. Marcajul longitudinal format dintr-o linie continuă simplă sau dublă, interzice încălcarea acestuia. Însă atunci când marcajul longitudinal este format dintr-o linie continuă și una discontinuă alăturate, conducătorul de vehicul trebuie să respecte semnificația liniei celei mai apropiate în sensul de mers. De exemplu, dacă linia cea mai apropiată în sensul de mers este cea discontinuă, marcajul longitudinal poate fi încălcat. Dar linia cea mai apropiată în sensul de mers este cea continuă, încălcarea marcajului longitudinal este interzisă. Încălcarea sau trecerea peste marcajul format dintr-o linie continuă, fie că este simplă sau dublă, este interzisă în orice situație. Prin urmare, chiar și atunci când drumul este în aliniament, iar vizibilitatea în față este asigurată, vă este interzisă încălcarea acestui marcaj.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0764.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0764.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 764; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 763 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-ce-situatie-se-poate-incalca-marcajul-longitudinal-continuu-al-axului-drumului","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"763","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0765","batch":"16","category":"Categoria B","question":"Cum procedați la semnalul polițistului cu brațul ridicat vertical?","answers":["Opriți, indiferent din ce direcție vă apropiați, și așteptați următorul său semnal","Reduceți viteza și circulați în direcția permisă de poziția brațului","Reduceți viteza și îl ocoliți"],"correctIndices":[0],"correct":0,"explanation":"Brațul polițistului rutier ridicat vertical semnifică „Atenție, oprire!” pentru toți participanții la trafic care se apropie, cu excepția conducătorilor de vehicule care nu ar mai putea opri în condiții de siguranță. Dacă semnalul este dat într-o intersecție, acesta nu impune oprirea conducătorilor de vehicule care se află deja angajați în traversare. Prin urmare, la semnalul polițistului rutier cu brațul ridicat vertical trebuie să opriți și să așteptați următorul semnal al acestuia.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0765.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0765.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 765; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 764 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedati-la-semnalul-politistului-cu-bratul-ridicat-vertical","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"764","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0766","batch":"16","category":"Categoria B","question":"În care dintre situații este permisă depășirea?","answers":["În intersecțiile dirijate prin semnale sonore","În intersecțiile dirijate","În intersecțiile nedirijate"],"correctIndices":[1],"correct":1,"explanation":"Legislația rutieră NU interzice efectuarea manevrei de depășire în intersecțiile cu circulație dirijată, nici în cele în care circulația se desfășoară în sens giratoriu, acestea fiind considerate tot intersecții cu circulație dirijată. Însă legislația rutieră interzice această manevră în intersecțiilecu circulație nedirijată.Atenție!În intersecțiilecu circulație nedirijatăse interzice depășirea tuturor vehiculelor, chiar și depășirea bicicletelor sau trotinetelor electrice.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0766.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0766.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 766; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 765 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-care-dintre-situatii-este-permisa-depasirea","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"765","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0767","batch":"16","category":"Categoria B","question":"Se pedepsesc penal următoarele acțiuni:","answers":["Instalarea de mijloace de semnalizare rutieră sau modificarea poziției acestora fără autorizație legală","Organizarea sau participarea, în calitate de conducător auto sau de animale, la întreceri neautorizate pe drumurile publice","Blocarea cu intenție a drumului public, dacă se pune în pericol siguranță circulației"],"correctIndices":[0,1,2],"correct":0,"explanation":"Se interzice instalarea de mijloace de semnalizare rutieră sau modificarea poziției acestora fără autorizație legală, precum și organizarea sau participarea, în calitate de conducător auto sau conducător de animale, la întreceri neautorizate pe drumurile publice și, de asemenea, se interzice și blocarea cu intenție a drumului public, dacă se pune în pericol siguranța circulației. Acestea fapte sunt considerate infracțiuni și se pedepsesc penal, cu închisoare sau amendă penală.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0767.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0767.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 767; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 766 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/se-pedepsesc-penal-urmatoarele-actiuni","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"766","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0768","batch":"16","category":"Categoria B","question":"În ce situație vă este permis să opriți vehiculul sau să staționați pe partea stângă a sensului de mers?","answers":["Pe drumurile cu sens unic, dacă rămâne liberă cel puțin o bandă de circulație","Pe drumurile secundare","Pe drumurile cu cel puțin două benzi pe sens"],"correctIndices":[0],"correct":0,"explanation":"De regulă, oprirea sau staționarea vehiculelor se face pe partea dreaptă a drumului, cât mai aproape de marginea din dreapta a drumului și paralel cu aceasta. Dar prin excepție, în localități, pe drumurile cu sens unic, oprirea sau staționarea voluntară a vehiculelor este permisă și pe partea stângă, dacă rămâne liberă cel puțin o bandă de circulație.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0768.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0768.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 768; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 767 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-ce-situatie-va-este-permis-sa-opriti-vehiculul-sau-sa-stationati-pe-partea-stanga-a-sensului-de-mers","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"767","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0769","batch":"16","category":"Categoria B","question":"Dacă un drum public este neiluminat, este permisă staționarea vehiculelor pe partea carosabilă?","answers":["Da, dacă sunt aprinse luminile de poziție sau de staționare","Da, dar numai în interiorul localităților","Nu"],"correctIndices":[0],"correct":0,"explanation":"Un vehicul poate fi oprit sau staționat pe partea carosabilă a unui drum cu toate luminile stinse atunci când drumul este iluminat, iar vehiculul este vizibil de la cel puțin 50 de metri.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0769.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0769.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 769; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 768 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/daca-un-drum-public-este-neiluminat-este-permisa-stationarea-vehiculelor-pe-partea-carosabila","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"768","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0770","batch":"16","category":"Categoria B","question":"Cum puteți folosi în condiții optime capacitatea de frânare a motorului, atunci când coborâți o pantă lungă și înclinată?","answers":["Schimbați într-o treaptă superioară","Schimbați la timp într-o treaptă inferioară","După schimbarea vitezei, aduceți imediat maneta în „punctul mort“"],"correctIndices":[1],"correct":1,"explanation":"Atunci când coborâți o pantă lungă și înclinată, pentru a putea folosi în condiții optime capacitatea de frânare a motorului, trebuie să schimbați la timp într-o treaptă inferioară de viteză. Astfel veți beneficia de frâna de motor și veți reduce semnificativ uzura sistemului de frânare (frâna de picior). Atunci când coborâți o pantă lungă și înclinată folosind frâna de serviciu (frâna de picior) vom ține pedala de frână apăsată o perioadă relativ mare de timp. Asta înseamnă că sistemul de frânare va lucra un timp îndelungat, încercând să reducă viteza de deplasare a mașinii. Astfel suprafața de contact dintre plăcuțe și disc se va supraîncălzi și gradul de aderență dintre cele două suprafețe va scădea. Toate acestea ducând la o eficiență scăzută a sistemului de frânare cauzată de supraîncălzire. Acest fenomen se numește „oboseală a sistemului de frânare”.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0770.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0770.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 770; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 769 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-puteti-folosi-in-conditii-optime-capacitatea-de-franare-a-motorului-atunci-cand-coborati-o-panta-lunga-si-inclinata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"769","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0771","batch":"16","category":"Categoria B","question":"Ce înțelegeți prin conduită preventivă în condiții atmosferice nefavorabile?","answers":["Rulați cu o viteză mai mică decât viteza maximă legală, admisă pe tronsonul de drum respectiv","Conduceți cu atenție sporită și cu o viteză care să vă permită oprirea în siguranță și evitarea oricărui pericol","Folosiți atât luminile de drum cât și cele de avarie, pentru a fi mai ușor de observat"],"correctIndices":[1],"correct":1,"explanation":"Dacă de exemplu pe o autostradă, unde viteza maximă este de 130 de km/h, rulați cu 125 de km/h pe timp de ploaie (condiții atmosferice nefavorabile), este foarte riscant și înseamnă că nu respectați condițiile circulației preventive. Prin urmare, această variantă de răspuns nu poate fi corectă, din punct de vedere al conduitei preventive. Conduita preventivă în condiții atmosferice nefavorabile reprezintă o conducere cu atenție sporită și cu o viteză care să vă permită oprirea în condiții de siguranță și evitarea oricărui pericol. Luminile de drum (faza lungă) se vor folosi în condiții atmosferice normale în funcție de cât de iluminat este drumul public. Iar noaptea se pot folosi doar dacădin sens opusnu se apropie un alt vehicul la mai puțin de 200 de metri iarîn față,în același sens, nu circulă alt vehicul la mai puțin de 100 de metri.Condițiile atmosferice nefavorabile nu vă permit folosirea luminilor de drum (faza lungă) în permanență.Prin urmare, această variantă de răspuns nu poate fi corectă, din punct de vedere al conduitei preventive.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0771.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0771.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 771; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 770 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-intelegeti-prin-conduita-preventiva-in-conditii-atmosferice-nefavorabile","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"770","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0772","batch":"16","category":"Categoria B","question":"La o intersecție semaforizată, semnalul verde se schimbă în galben. Conducătorul unui vehicul, fiind foarte aproape de semafor, oprește brusc și este lovit din spate de conducătorul care îl urma. Care dintre cei doi conducători a greșit?","answers":["Conducătorul primului vehicul, care a oprit brusc","Conducătorul vehiculului din spate, care nu a păstrat distanța de siguranță în mers","Ambii conducători"],"correctIndices":[1],"correct":1,"explanation":"Conducătorul unui vehicul care circulă în spatele altuia are obligația de a păstra o distanță suficientă față de acesta,pentru evitarea coliziunii. Această obligație trebuie respectată întotdeauna. În situația în care semaforul își schimbă culoarea din verde în galben iar conducătorul vehiculului din față oprește brusc și conducătorul vehiculului din spate îl lovește pe acesta, cel care a greșit este conducătorul vehiculului din spate, deoarecenu a păstrat o distanță suficientă pentru evitarea coliziunii, în situația în care cel din fată reduce viteza sau frânează brusc. Nepăstrarea acestei distanțe, dacă prin aceasta s-a produs un accident din care au rezultat avarierea unui vehicul sau alte pagube materiale, se sancționează cu amenda prevăzută în clasa a II-a de sancțiuni și cu aplicarea a 3 puncte de penalizare.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0772.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0772.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 772; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 771 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/la-o-intersectie-semaforizata-semnalul-verde-se-schimba-in-galben-conducatorul-unui-vehicul-fiind-foarte-aproape-de-semafor-opreste-brusc-si","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"771","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0773","batch":"16","category":"Categoria B","question":"Ce obligații aveți la semnalul membrilor patrulelor școlare de circulație, la trecerile pentru pietoni din apropierea unităților de învățământ?","answers":["Să reduceți viteza și să circulați cu atenție","Să treceți pe banda de lângă axul drumului","Să opriți"],"correctIndices":[2],"correct":2,"explanation":"Atunci când conduceți un vehicul și observați membri ai patrulelor școlare de circulație, la trecerile pentru pietoni din apropierea unităților de învățământ, care vă adresează semnale de oprire, aveți obligația de a opri, permițând respectivei patrule să traverseze strada. Prin urmare, într-o astfel de situație, nu este de ajuns doar să reduceți viteza și să circulați cu atenție, deoarece oprirea este obligatorie. A nu se confunda „membri ai patrulelor școlare de circulație” cu „grupurile organizate”, la trecere pe lângă care aveți obligația de a circula cu o viteză care să nu depășească 30 km/h în localități sau 50 km/h în afara localităților, atunci când acestea se află în mers sau staționează pe partea carosabilă a drumurilor cu o singură bandă de circulație pe sens. Atunci când conduceți un vehiculNUaveți obligația de a trece pe banda de lângă axul drumului la semnalele date de membrii patrulelor școlare de circulație, la trecerile pentru pietoni din apropierea unităților de învățământ. Mai mult de atât, acest lucruNUvă este permis, având în vedere că aveți obligațiade a oprila semnalele acestora. Atunci când conduceți un vehiculaveți obligația de a oprila semnalele date de membrii patrulelor școlare de circulație, la trecerile pentru pietoni din apropierea unităților de învățământ.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0773.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0773.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 773; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 772 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-aveti-la-semnalul-membrilor-patrulelor-scolare-de-circulatie-la-trecerile-pentru-pietoni-din-apropierea-unitatilor-de-invataman","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"772","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0774","batch":"16","category":"Categoria B","question":"Intenționați să transportați o încărcătură cu autoturismul personal. Ce trebuie să aveți în vedere?","answers":["În față, încărcătura poate depăși cu un metru limitele vehiculului","Încărcătura să nu fie voluminoasă","Să nu fie depășite lungimea, lățimea și greutatea admise"],"correctIndices":[2],"correct":2,"explanation":"Încărcăturanu trebuie să depășească deloc lungimea și lățimea autoturismului în toate părțile, nu doar în față și cu mai mult de un metru. Indiferent dacă încărcătura este sau nu voluminoasă, este important ca aceasta să nu depășească lungimea și lățimea autoturismului. Atunci când transportați o încărcătură cu autoturismul, trebuie să aveți în vedere că vă este interzis să transportați, în și pe autoturism, obiecte a căror lungime sau lățime depășește, împreună cu încărcătura, dimensiunile acestuia sau depășește greutatea admisă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0774.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0774.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 774; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 773 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/intentionati-sa-transportati-o-incarcatura-cu-autoturismul-personal-ce-trebuie-sa-aveti-in-vedere","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"773","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0775","batch":"16","category":"Categoria B","question":"Ce trebuie să aibă în vedere prima intervenție, la fața locului, pentru salvarea victimei?","answers":["Spălarea rănilor vizibile","Degajarea căilor respiratorii și asigurarea funcției respiratorii","Igienizarea și pansarea rănilor"],"correctIndices":[1],"correct":1,"explanation":"Prima intervenție care trebuie avută în vedere pentru salvarea victimei când ajungeți la fața locului unui accident este să vă asigurați dacă victima poate respira, iar dacă aceasta are căile respiratorii astupate, se trece la degajarea căilor respiratorii și asigurarea funcției respiratorii.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0775.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0775.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 775; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 774 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-trebuie-sa-aiba-in-vedere-prima-interventie-la-fata-locului-pentru-salvarea-victimei","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"774","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0776","batch":"16","category":"Categoria B","question":"Temperatura lichidului de răcire care asigură performanța maximă și uzura minimă a motorului este cuprinsă în intervalul:","answers":["100-120 grade c","60-70 grade c","90-95 grade c"],"correctIndices":[2],"correct":2,"explanation":"Temperatura lichidului de răcire care asigură performanța maximă și uzura minimă a motorului este cuprinsă în intervalul 90-95 grade Celsius. Instalația de răcire a motorului are rolul de a asigura o temperatură optimă a motorului (90-95 grade Celsius). Temperatura din interiorul motorului poate atinge 2000° C în momentul combustiei. Deci este necesară răcirea pentru a evita dilatarea excesivă a pieselor, care ar genera blocarea (griparea) motorului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0776.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0776.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 776; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 775 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/temperatura-lichidului-de-racire-care-asigura-performanta-maxima-si-uzura-minima-a-motorului-este-cuprinsa-in-intervalul","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"775","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0777","batch":"16","category":"Categoria B","question":"Indicatorul vă avertizează că urmează:","answers":["Un drum cu denivelări","Un segment de drum pe care se execută lucrări de amenajare","O denivelare pentru limitarea vitezei"],"correctIndices":[2],"correct":2,"explanation":"Indicatorul din imagine face parte din categoria indicatoarelor de avertizare și se numește „Denivelare pentru limitarea vitezei”. Acest indicator vă avertizează că urmează o denivelare amplasată pe carosabil cu intenția de a impune reducerea vitezei, acestea se mai numesc și „limitatoare de viteză” și se instalează în zona unor obiective cu caracter special (cum ar fi: școli, spitale etc.). Indicatorul „Denivelare pentru limitarea vitezei” este precedat de indicatorul „Limitare de viteză”, iar în unele cazuri se pot găsi instalate ambele pe același suport. Regulamentul rutier obligă ca la deplasarea pe drumuri cu denivelări, semnalizate ca atare, să circulați cu o viteză care să nu depășească 30 km/h în localități sau 50 km/h în afara localităților.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0777.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0777.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 777; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un drum urban îngust, cu mașini parcate pe ambele părți și un indicator triunghiular cu margini roșii și o cocoașă neagră în mijloc, ce avertizează apariția unei denivelărî pentru limitarea vitezei.","needsImageReview":true,"source":"RoDrive · ID 776 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/indicatorul-va-avertizeaza-ca-urmeaza","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"776","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_801.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0778","batch":"16","category":"Categoria B","question":"Interdicția impusă de indicatorul din imagine se adresează:","answers":["Tuturor autovehiculelor, cu excepția motocicletelor fără ataș","Autoturismelor și motocicletelor","Tuturor vehiculelor"],"correctIndices":[0],"correct":0,"explanation":"Indicatorul se numește “Accesul interzis autovehiculelor, cu excepția motocicletelor fără ataș”, acest indicator interzice accesul tuturor autovehiculelor, adică tuturor vehiculelor cu motor, cu excepția motocicletelor fără ataș. În situația dată nu puteți pătrunde pe acest sector de drum, indicatorul permite accesul motocicletelor fără ataș, ciclomotoarelor (mopedelor) și vehiculelor fără motor.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0778.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0778.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 778; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Indicatorul circular din intersecție cu chenar roșu și simbolul unei mașini semnifică 'Acces interzis autovehiculelor, cu excepția motocicletelor fără ataș'.","needsImageReview":true,"source":"RoDrive · ID 777 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/interdictia-impusa-de-indicatorul-din-imagine-se-adreseaza","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"777","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_802.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0779","batch":"16","category":"Categoria B","question":"Cum se execută depășirea autoturismelor și a autocamioanelor pe un drum fără marcaje, pe care circulația se desfășoară în sens unic?","answers":["Pe partea stângă","Pe partea dreaptă","Pe ambele părți"],"correctIndices":[0],"correct":0,"explanation":"Depășirea vehiculelor, chiar și a autoturismelor sau a autocamioanelor, se efectuează numai pe partea stângă a acestora, indiferent dacă manevra se efectuează pe un drum cu sens unic sau pe un drum cu dublu sens de circulație. Atragem atenția că în această întrebare nu este vorba despre un drum cu două sau mai multe benzi de circulație pe sens ci este vorba despre un drum care nu are marcaje, caz în care se consideră a fi un drum cu o singură bandă de circulație pe sens și nu poate fi vorba despre o devansare.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0779.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0779.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 779; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 778 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-se-executa-depasirea-autoturismelor-si-a-autocamioanelor-pe-un-drum-fara-marcaje-pe-care-circulatia-se-desfasoara-in-sens-unic","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"778","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0780","batch":"16","category":"Categoria B","question":"La întâlnirea unui vehicul care circulă noaptea, din sens opus, pe un drum neiluminat, conducătorul de autovehicul este obligat:","answers":["Să circule cât mai aproape de marginea din dreapta a drumului","Să reducă viteza","Să folosească avertizorul sonor"],"correctIndices":[1],"correct":1,"explanation":"Nu aveți obligația de a circula cât mai aproape de marginea din dreapta a drumului la întâlnirea unui vehicul care circulă noaptea, din sens opus, indiferent dacă drumul este sau nu iluminat. Este posibil să încurcați această situație cu situația în care sunteți depășit de un alt vehicul, caz în care aveți obligația de a circula cât mai aproape de marginea din dreapta a părții carosabile sau a benzii pe care vă deplasați și să nu măriți viteza de deplasare. Acordați atenție acestor două situații pentru a nu le confunda! Când circulați pe timpul nopții, indiferent dacă drumul este sau nu iluminat, la apropierea de un alt vehicul care circulă din sens opus (vine din sens opus spre vehiculul pe care îl conduceți), sunteți obligat ca de la distanța de cel puțin 200 de metri să folosiți luminile de întâlnire, concomitent cu reducerea vitezei.În cazul în care în acel moment circulați cu luminile de drum (faza lungă) în funcțiune, trebuie să le schimbați cu luminile de întâlnire (faza scurtă), pentru a nu-i deranja pe cei din față, concomitent cu reducerea vitezei de deplasare.În cazul în care în acel moment circulați având în funcțiune, în schimbul luminilorde întâlnire, luminile pentru circulația diurnă (DRL), trebuie să aprindeți luminile de întâlnire (faza scurtă), concomitent cu reducerea vitezei de deplasare. Trebuie să facem diferența între următoarele două situații pe care le întâlnim în întrebările din chestionare dar și în traficul de zi cu zi: Legislația rutieră nu prevede obligativitatea de a folosi avertizorul sonor în această situație.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0780.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0780.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 780; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 779 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/la-intalnirea-unui-vehicul-care-circula-noaptea-din-sens-opus-pe-un-drum-neiluminat-conducatorul-de-autovehicul-este-obligat","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"779","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0781","batch":"16","category":"Categoria B","question":"În ce ordine vor trece autovehiculele prin intersecția prezentată?","answers":["Tramvaiul 1, tramvaiul 2, autoturismul","Tramvaiul 2, tramvaiul 1, autoturismul","Tramvaiul 1, autoturismul, tramvaiul 2"],"correctIndices":[0],"correct":0,"explanation":"Intersecția din imagine este dirijată prin indicatoare de reglementare de prioritate, sub fiecare indicator se găsește instalat cate un panou adițional care ne indica direcția drumului cu prioritate. Tramvaiul 2 și autoturismul vin de pe drumuri fără prioritate, întâlnind indicatorul “Cedează trecerea” și au obligația de a acorda prioritate de trecere. Tramvaiul 1 circulă pe drumul cu prioritate întâlnind indicatorul “Drum cu prioritate” și va trece primul prin intersecție. Între tramvaiul 2 și autoturism s-a creat o situație de egalitate, deoarece ambele întâlnesc indicatorul “Cedează trecerea”, situație în care se va aplica regula priorității de dreapta, autoturismul îi va acorda prioritate de trecere tramvaiului 2 deoarece acesta îi vine din partea dreaptă. Ordinea de trecere este următoarea: tramvaiul 1, urmat de tramvaiul 2 iar ultiumul prin intersecție va trece autoturismul.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0781.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0781.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 781; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție nesemaforizată cu două tramvaie și un autoturism. Tramvaiul marcat cu numărul 1 merge la stânga și vine din stânga, având în față un indicator romboid galben cu margine albă, cu un panou adițional ce îngroașă drumul din direcția sa către stânga, evidențiind drumul prioritar, acela indicat anterior. Tramvaiul marcat cu numărul 2 merge înainte și vine de sus. Autoturismul vine de jos și merge înainte.","needsImageReview":true,"source":"RoDrive · ID 780 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-ce-ordine-vor-trece-autovehiculele-prin-intersectia-prezentata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"780","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_507.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0782","batch":"16","category":"Categoria B","question":"Cum procedați în intersecția care urmează?","answers":["Traversați fără să acordați prioritate","Traversați după ce acordați prioritate de dreapta","Traversați după ce acordați prioritate de stânga"],"correctIndices":[0],"correct":0,"explanation":"Semnificația semnalelor semafoarelor se va respecta cu prioritate față de indicatoarele de reglementare de prioritate. În situația dată, întâlnind semnalul verde al semaforului, respectați semnificația acestui semnal, indicatorul “Cedează trecerea”, se va respecta în situația când semaforul nu funcționează sau funcționează pe culoarea galben intermitent. Prin urmare, în această situație veți intra în intersecție fără să acordați prioritate de trecere, deoarece semnalul verde al semaforului va permite trecerea.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0782.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0782.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 782; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție cu un semafor verde și un indicator triunghiular cu margini roșii 'Cedează trecerea'.","needsImageReview":true,"source":"RoDrive · ID 781 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedati-in-intersectia-care-urmeaza","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"781","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_806.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0783","batch":"16","category":"Categoria B","question":"Indicatorul din imagine vă avertizează că:","answers":["Următoarea intersecție este dirijată prin semnale luminoase","Urmează o stație de transport public de persoane","În următoarea intersecție nu funcționează semnalizarea luminoasă"],"correctIndices":[0],"correct":0,"explanation":"Indicatorul pe care l-ați întâlnit se numește “Semafoare”. Acest indicator vă avertizează că vă apropiați de o intersecție dirijată prin semafoare luminoase, intersecție în care prezența semafoarelor v-ar putea lua prin surprindere.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0783.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0783.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 783; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Indicatorul triunghiular cu margini roșii și cu semafor în interior avertizează că urmează o intersecție dirijată prin semafoare luminoase.","needsImageReview":true,"source":"RoDrive · ID 782 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/indicatorul-din-imagine-va-avertizeaza-ca","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"782","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_807.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0784","batch":"16","category":"Categoria B","question":"Cât timp trebuie menținută semnalizarea schimbării direcției de mers?","answers":["10 secunde de la începerea manevrei","Pe întreaga durată a executării manevrei","Legea nu prevede nimic cu privire la acest aspect"],"correctIndices":[1],"correct":1,"explanation":"Conducătorul vehiculului este obligat să semnalizeze din timp intenția de a schimba direcția de mers, cu cel puțin 50 de metri în localități și 100 de metri în afara localităților înainte de începerea efectuării manevrei și să mențină în funcțiune semnalizarea schimbării direcției de mers pe întreaga durată a executării manevrei.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0784.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0784.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 784; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 783 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cat-timp-trebuie-mentinuta-semnalizarea-schimbarii-directiei-de-mers","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"783","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0785","batch":"16","category":"Categoria B","question":"Cum veți proceda în intersecție, dacă circulați pe drumul prioritar?","answers":["Cedați trecerea vehiculelor care vin din dreapta","Cedați trecerea tuturor vehiculelor","Nu cedați trecerea niciunui vehicul"],"correctIndices":[2],"correct":2,"explanation":"În această intersecție dirijată cu indicatoare de reglementare de prioritate întâlniți indicatorul “Drum cu prioritate” însoțit de un panou adițional care indică direcția drumului cu prioritate. Dumneavoastră, circulând pe drumul prioritar, nu trebuie să acordați prioritate de trecere, deoarece aveți prioritate.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0785.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0785.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 785; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție semnalizată cu indicatorul 'Drum cu prioritate'","needsImageReview":true,"source":"RoDrive · ID 784 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-veti-proceda-in-intersectie-daca-circulati-pe-drumul-prioritar","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"784","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_809.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0786","batch":"16","category":"Categoria B","question":"În situația în care polițistul se află cu fața la un autovehicul care se apropie, având brațul drept întins orizontal, conducătorul auto trebuie:","answers":["Să oprească, deoarece semnalul i se adresează","Să continue deplasarea, deoarece semnalul nu i se adresează","Să schimbe direcția de mers spre stânga"],"correctIndices":[1],"correct":1,"explanation":"Atunci când întâlniți un polițist care se află cu fața către dvs., având brațul drept întins orizontal, vă puteți continua deplasarea, deoarece direcția dvs. de deplasare nu se intersectează cu brațul ridicat al polițistului. În situația descrisă, trebuie să oprească cei care vin din spatele polițistului, direcția acestora de deplasare se intersectează cu brațul ridicat al acestuia. Acest semnal al polițistului deși se va întâlni, de regula, în intersecții, poate fi efectuat și în alte locuri, nu doar în intersecții. Trebuie ținut cont că în întrebările din chestionare, când nu se specifică locul în care polițistul se află poziționat, se înțelege că acesta este poziționat în mijlocul intersecției.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0786.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0786.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 786; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 785 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-situatia-in-care-politistul-se-afla-cu-fata-la-un-autovehicul-care-se-apropie-avand-bratul-drept-intins-orizontal-conducatorul-auto-trebu","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"785","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0787","batch":"16","category":"Categoria B","question":"Cum procedați la apropierea de o intersecție în care semnalul luminos ori un indicator de prioritate permite intrarea, dar în care riscați să rămâneți imobilizat din cauza aglomerării circulaţiei?","answers":["Vă este interzisă intrarea în intersecție","Vă continuați deplasarea, deoarece aveți prioritate","Nu vă revine nicio obligație"],"correctIndices":[0],"correct":0,"explanation":"În situația în care doriți să pătrundeți într-o intersecție, dar aceasta este blocată din cauza aglomerației, chiar dacă semnalul semaforului este verde și vă permite trecerea, vă este interzisă pătrunderea în acea intersecție, caz în care trebuie să opriți și să așteptați deblocarea intersecției. După deblocarea acesteia, puteți pătrunde în intersecție doar la culoarea verde a semaforului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0787.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0787.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 787; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 786 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedati-la-apropierea-de-o-intersectie-in-care-semnalul-luminos-ori-un-indicator-de-prioritate-permite-intrarea-dar-in-care-riscati-sa","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"786","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0788","batch":"16","category":"Categoria B","question":"Ce obligații aveți în situația prezentată?","answers":["Să circulați cu viteză redusă și să traversați calea ferată, dacă bariera sau semibariera este ridicată","Să opriți în dreptul indicatorului","Să măriți viteza, pentru a nu fi surprins de închiderea barierelor"],"correctIndices":[0],"correct":0,"explanation":"În această situație întâlniți indicatorul „Trecere la nivel cu o cale ferată cu bariere sau semibariere”, care vă avertizează că vă apropiați de o trecere la nivel cu o cale ferată cu bariere sau semibariere, loc în care aveți obligația de a reduce viteza de deplasare. Prin urmare, în situația dată trebuie să circulați cu viteză redusă și, chiar dacă barierele sunt ridicate, și vi se permite trecerea, trebuie să vă asigurați că din partea stângă sau din partea dreaptă nu circulă un vehicul feroviar, după care traversați calea ferată.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0788.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0788.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 788; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"O intersecție din perspectiva unui șofer, ce prezintă indicatorul triunghiular cu margini roșii și gard negru, care semnifică 'Trecere la nivel cu calea ferată cu bariere'.","needsImageReview":true,"source":"RoDrive · ID 787 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-aveti-in-situatia-prezentata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"787","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_812.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0789","batch":"16","category":"Categoria B","question":"Aveți obligația de a opri imediat vehiculul la semnalele adresate de:","answers":["Polițiștii de frontieră","Polițiștii comunitari","Personalul autorizat din cadrul serviciului de examinări"],"correctIndices":[0],"correct":0,"explanation":"Pe lângă obligația de a opri la semnalele polițistului rutier, participanții la trafic sunt obligați să oprească imediat și la semnalele adresate în acest sens de cătrepolițiștii de frontieră. Aceștia din urmă pot efectua, pe lângă semnalele de oprire, și următoarele semnale: balansarea brațului în plan vertical, cu palma mâinii orientată către sol sau cu un mijloc de semnalizare, care semnifică reducerea vitezei, precum și rotirea vioaie a brațului, care semnifică mărirea vitezei de deplasare a vehiculelor, inclusiv grăbirea traversării drumului de către pietoni. Nerespectarea acestor semnale se sancționează cu amendă prevăzută în clasa a II-a de sancțiuni.. Legislația rutieră nu prevede obligația de a opri la semnalele adresate de polițiștii comunitari. Din anul 2010 termenul „poliție comunitară” nu mai există în actele normative în vigoare. În acest moment termenul care se găsește în actele normative în vigoare este „poliție locală”. Legislația rutieră nu prevede ca personalul autorizat din cadrul serviciului examinări să poată adresa semnale de oprire. Prin urmare, aceștia nu pot adresa semnale de oprire conducătorilor de vehicule.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0789.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0789.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 789; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 788 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/aveti-obligatia-de-a-opri-imediat-vehiculul-la-semnalele-adresate-de","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"788","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0790","batch":"16","category":"Categoria B","question":"Ce semnificație are indicatorul din imagine?","answers":["Urmează un sector de drum îngustat temporar","Este interzisă schimbarea direcției de mers la dreapta în prima intersecție","Urmează o intersecție cu un drum fără prioritate"],"correctIndices":[2],"correct":2,"explanation":"Indicatorul pe care l-ați întâlnit se numește “Intersecție cu un drum fără prioritate”, acest indicator vă avertizează că urmează o intersecție cu un drum fără prioritate, intersecție în care veți avea prioritate de trecere. Simbolul de pe indicator sugerează configurația intersecției, în acest caz intersecția fiind în formă de ” T ”, drumul fără prioritate aflându-se în partea dreaptă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0790.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0790.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 790; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un indicator triunghiular cu margini roșii cu o săgeată groasă neagră în sus, având în dreapta o linie orizontală scurtă, neagră, care semnifică 'Intersecție cu un drum fără prioritate'.","needsImageReview":true,"source":"RoDrive · ID 789 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-semnificatie-are-indicatorul-din-imagine","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"789","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_814.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0791","batch":"16","category":"Categoria B","question":"Indicatorul din imagine semnifică:","answers":["„copii“","„alte pericole“","„ambuteiaj“"],"correctIndices":[1],"correct":1,"explanation":"Indicatorul se numește “Alte pericole”, acesta vă avertizează despre apropierea de un loc periculos care nu are un indicator specific. La întâlnirea acestui indicator se recomandă sporirea atenției pentru a putea observa din timp eventualele pericole astfel semnalizate. Acest indicator se găsește instalat și la trecerea la nivel cu o cale ferată industrială, însoțit de unpanou adiţionalce conține imaginea unei locomotive.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0791.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0791.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 791; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un indicatorul triunghiular cu semnul exclamării în mijloc și avertizează șoferul asupra unui pericol nespecificat.","needsImageReview":true,"source":"RoDrive · ID 790 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/indicatorul-din-imagine-semnifica","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"790","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_815.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0792","batch":"16","category":"Categoria B","question":"Este permisă întoarcerea pe autostradă?","answers":["Nu","Da","Da, dacă sensul de mers este blocat"],"correctIndices":[0],"correct":0,"explanation":"Pe autostradă este interzisă manevra de întoarcere, deoarece se interzice manevra de oprire, iar întoarcerea este interzisă acolo unde aste interzisă manevra de oprire. Se interzice întoarcerea chiar și atunci când pentru această manevra se folosește spațiul interzis care separă sensurile de circulație sau racordurile dintre cele două părți carosabile.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0792.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0792.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 792; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un sector de autostradă ('Autostrada Soarelui') cu indicatoare rutiere suspendate. Indicatoarele semnalizează direcția către Constanța pe autostrada A2 și limitele de viteză specifice: 130 km/h pentru autoturisme. De asemenea, sunt afișate interdicții precum accesul interzis pietonilor, vehiculelor lente și bicicletelor.","needsImageReview":true,"source":"RoDrive · ID 791 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/este-permisa-intoarcerea-pe-autostrada","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"791","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_816.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0793","batch":"16","category":"Categoria B","question":"Când ninge abundent veți folosi:","answers":["Luminile de poziție","Claxonul","Luminile de întâlnire ale farurilor"],"correctIndices":[2],"correct":2,"explanation":"Pentru variantaA Luminile de poziție sunt folositepe timpul imobilizăriivehiculului pe partea carosabilă în afara localităților, de la lăsarea serii și până în zorii zilei, ziua când plouă torențial, ninge abundent sau este ceață densă ori în alte condiții care reduc vizibilitatea pe drumul public. Mijloacele de avertizare sonoră (claxonul) sunt folosite pentru avertizarea sonoră în scopul evitării unui pericol imediat. Legislația nu prevede folosirea avertizorului sonor (claxonului) ca măsură necesară pentru deplasare în condiții de ninsoare abundentă. Atunci când plouă torențial, ninge abundent ori în alte condiții care reduc vizibilitatea pe drum, conducătorii de autovehicule, tractoare agricole sau forestiere și tramvaie sunt obligați să folosească luminile de întâlnire. Acestea sunt adecvate pentru a asigura vizibilitatea necesară și pentru a evita orbirea celorlalți participanți la trafic. Deși legislația rutieră a fost actualizată iar în acest moment este obligatoriu ca la circulațiape timpul zilei, pe toate categoriile de drum public, să se circule având în funcțiune luminile de întâlnire (faza scurtă)sauluminile pentru circulația diurnă (DRL), răspunsul la această întrebare rămâne în continuare corect și conform cu legislația. Pentru a înțelege mai bine această regulă dăm următorul exemplu: Un conducător de autovehicul circulă pe timpul zilei,în condiții optime de vizibilitate, caz în care are obligația de a pune în funcțiunefie luminile de întâlnire(adică faza scurtă),fie luminile pentru circulația diurnă(DRL), după cum consideră acesta, ori poate chiar să le folo","imageUrl":"/nivel-1/quiz-images/rodrive-all/0793.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0793.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 793; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea arată condiții meteorologice nefavorabile, cu vizibilitate redusă din cauza zăpezii. Ștergătoarele sunt în funcțiune, dar parțial eficiente.","needsImageReview":true,"source":"RoDrive · ID 792 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cand-ninge-abundent-veti-folosi","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"792","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_817.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0794","batch":"16","category":"Categoria B","question":"Care dintre vehicule trebuie să acorde prioritate pietonilor?","answers":["Vehiculul pe care îl conduceți","Autocamionul galben","Ambele vehicule"],"correctIndices":[0],"correct":0,"explanation":"Conducătorul de vehicul este obligat să acorde prioritate de trecere pietonului care traversează drumul public, prin loc special amenajat, marcat și semnalizat corespunzător ori la culoarea verde a semaforului destinat lui, atunci când acesta se afla pe sensul de mers al vehiculului. Deci în situația dată pietonii aflându-se în traversare pe sensul dumneavoastră de mers trebuie să opriți și să le acordați prioritate, autocamionul galben nu are această obligație deoarece pietonii nu se află pe sensul acestuia de mers.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0794.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0794.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 794; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o trecere de pietoni semnalizată corespunzător, din perspectiva unui șofer, vehiculul pe care îl conduceți. Doi pietoni traversează strada, iar un camion și șoferul se apropie de trecere. Pietonii se află pe sensul de mers al autoturismului.","needsImageReview":true,"source":"RoDrive · ID 793 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-dintre-vehicule-trebuie-sa-acorde-prioritate-pietonilor","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"793","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_818.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0795","batch":"16","category":"Categoria B","question":"Dacă virați la stânga:","answers":["Aveți prioritate de trecere","Părăsiți drumul cu prioritate","Cedați trecerea celor care vin din dreapta"],"correctIndices":[0],"correct":0,"explanation":"În această intersecție, dirijată cu indicatoare de reglementare de prioritate, întâlniți indicatorul “Drum cu prioritate” însoțit de un panou adițional care indică direcția drumului cu prioritate. Dumneavoastră, virând catre stânga, circulați pe drumul cu prioritate și aveți prioritate de trecere.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0795.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0795.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 795; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție semnalizată cu trei indicatoare: 'Trecere la nivel cu calea ferată fără bariere', 'Drum cu prioritate' (romb galben) și 'Intersecție cu linie de tramvai'. Un panou adițional sub indicatorul cu romb galben evidențiază drumul spre stânga.","needsImageReview":true,"source":"RoDrive · ID 794 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/daca-virati-la-stanga","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"794","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_819.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0796","batch":"16","category":"Categoria B","question":"Care este ordinea de trecere prin intersecție a celor trei vehicule?","answers":["Autoturismul roșu, autoturismul albastru, autobuzul","Autoturismul albastru, autoturismul roșu, autobuzul","Autobuzul, autoturismul albastru, autoturismul roșu"],"correctIndices":[0],"correct":0,"explanation":"Intersecția din imagine este dirijată cu indicatoare de reglementare de prioritate, sub fiecare indicator se găsește instalat câte un panou adițional care indică direcția drumului cu prioritate. Autoturismul roșu circulă pe drumul cu prioritate, autobuzul vine de pe un drum fără prioritate iar autoturismul albastru vine de pe drumul cu prioritate, însă circulând pe direcția înainte, părăsește drumul cu prioritate. Autobuzul trebuie să le acorde prioritate de trecere celor două autoturisme deoarece întâlnește indicatorul „Cedează trecerea”. Între autoturismul roșu și cel albastru s-a creat o situație de egalitate, ambele întâlnind indicatorul „Drum cu prioritate”, situație în care se va aplica regula priorității de dreapta, autoturismul albastru îi va acorda prioritate de trecere autoturismului roșu deoarece acesta îi vine din partea dreaptă. Ordinea de trecere este următoarea: autoturismul roșu, urmat de autoturismul albastru iar ultimul prin intersecție va trece autobuzul.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0796.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0796.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 796; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Această intersecție este reglementată prin indicatoare rutiere. Autoturismul albastru vine din dreapta și dorește să meargă înainte. Autoturismul roșu vine de jos, dorește să vireze la stânga și se află pe drumul prioritar. Autobuzul vine din dreapta și intenționează să vireze la stânga.","needsImageReview":true,"source":"RoDrive · ID 795 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-este-ordinea-de-trecere-prin-intersectie-a-celor-trei-vehicule","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"795","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_820.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0797","batch":"16","category":"Categoria B","question":"Ce semnificație are lumina de culoare roșie a semaforului, atât pentru conducătorii de vehicule, cât și pentru pietoni?","answers":["Îi obligă atât pe conducători, cât și pe pietoni să se oprească","Îi obligă pe conducători să oprească, iar pe pietoni să traverseze cu prudență","Permite vehiculelor să vireze la dreapta, cu respectarea priorității"],"correctIndices":[0],"correct":0,"explanation":"Semnalul de culoare roșie al semaforului interzice trecerea atat conducătorilor de vehicule cât și pietonilor.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0797.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0797.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 797; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 796 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-semnificatie-are-lumina-de-culoare-rosie-a-semaforului-atat-pentru-conducatorii-de-vehicule-cat-si-pentru-pietoni","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"796","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0798","batch":"16","category":"Categoria B","question":"Cum trebuie să procedeze conducătorul de vehicul atunci când circulă pe un drum cu trei sau mai multe benzi pe sens?","answers":["Să circule pe banda situată lângă acostament","Să nu circule pe liniile de tramvai","Să circule pe banda a doua, respectiv a treia, cu o viteză mai mică de 100 km/h"],"correctIndices":[0],"correct":0,"explanation":"Pe drumurile cu mai multe benzi de circulație pe sens, acestea se vor folosi în funcție de intensitatea traficului și viteza de deplasare, având obligația de a reveni pe prima bandă ori de cate ori este posibil. Deci se va circula pe cât posibil pe banda de lângă bordură sau acostament. Dacă drumul are 3 benzi iar pe una dintre benzi este amplasată linia tramvaiului, lângă axa drumului, conducătorii de vehicule pot folosi această bandă, cu obligația să lase liberă calea tramvaiului, la apropierea acestuia (art. 103 din Regulament). DE REȚINUT:folosirea acestei benzi este permisă doar dacă drumul are cel mult două benzi pe sens și o a treia pe care este amplasată linia tramvaiului. De exemplu, dacă drumul are 3 benzi pe sens și a patra bandă pe care este amplasată linia tramvaiului, această bandă nu poate fi folosită.Având în vedere că drumul din situația din întrebare este unul cu 3 sau mai multe benzi, varianta B nu este una corectă, pentru că pe drumul cu 3 benzi poți circula pe liniile de tramvai. De regulă, nu se impune o anumită viteză minimă sau maximă pentru a circula pe una dintre benzi, trebuie să respectați regimul legal de viteza (viteza maximă sau minimă) indiferent pe ce bandă de circulație vă aflați. Dar sunt și situații în care regimul legal de viteză se poate reglementa prin indicatoare și/sau marcaje speciale care să impună o viteză minimă sau maximă pe acea banda sau acele benzi.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0798.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0798.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 798; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 797 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-trebuie-sa-procedeze-conducatorul-de-vehicul-atunci-cand-circula-pe-un-drum-cu-trei-sau-mai-multe-benzi-pe-sens","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"797","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0799","batch":"16","category":"Categoria B","question":"Cum procedează conducătorul autovehiculului / tractorului agricol sau forestier, în situația în care vehiculul din fața sa schimbă direcția de mers spre stânga, iar pe partea dreaptă nu este loc suficient pentru depășire?","answers":["Semnalizează și execută depășirea cu viteză redusă","Încearcă depășirea prin stânga","Așteaptă eliberarea benzii pentru a-și continua deplasarea"],"correctIndices":[2],"correct":2,"explanation":"Vehiculul care a semnalizat și s-a încadrat corespunzător părăsirii sensului de mers spre stângase depășește prin partea dreapta, cu condiția ca spațiul rămas la dispoziție să permită efectuarea acestei manevre. Însă în situațiile în care în urma încadrării acestuia nu se creează spațiu suficient pentru efectuarea manevrei de depășire prin partea dreaptă, trebuie să opriți în spatele acestuia și să așteptați eliberarea benzii pentru a vă putea continua deplasarea. De reținut că depășirea acestor vehicule nu se va efectua prin partea stângă ci se va efectuanumai prin partea dreaptăiar dacă spațiul rămas la dispoziție nu permite efectuarea manevrei, nu este permis să se urce pe trotuar sau pe spațiile verzi pentru a o putea efectua.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0799.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0799.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 799; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 798 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedeaza-conducatorul-autovehiculului-tractorului-agricol-sau-forestier-in-situatia-in-care-vehiculul-din-fata-sa-schimba-directia-de-","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"798","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0800","batch":"16","category":"Categoria B","question":"Viteza maximă cu care pot să conducă un autoturism, pe drumurile naționale, altele decât cele europene (E), persoanele care au mai puțin de un an de practică de conducere, este de:","answers":["70 km/h","90 km/h","80 km/h"],"correctIndices":[0],"correct":0,"explanation":"Viteza maximă admisă pe drumurile Naționale din afara localităților, altele decat cele europene (E), pentru conducătorii de autovehicule din categoria B, este de 90 km/h. Însă viteza maximă admisă în afara localităților pentru autovehiculele ai căror conducători au mai puțin de un an practică de conducere este cu 20 km/h mai mică decât viteza maximă admisă. Din viteza maximă admisă de 90 km/h scădem cei 20 km/h și avem o diferență de 70 de km/h, astfel, viteza maximă admisă pentru aceștia este de 70 km/h.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0800.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0800.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 800; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 799 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/viteza-maxima-cu-care-pot-sa-conduca-un-autoturism-pe-drumurile-nationale-altele-decat-cele-europene-e-persoanele-care-au-mai-putin-de-un-an","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"799","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"}]);})();
